def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def_count = sum(1 for a in opp if a == 'D')
    my_def_count = sum(1 for a in my if a == 'D')
    opp_def_rate = opp_def_count / n

    # Exploit non-retaliating opponents
    retaliation_count = 0
    non_retaliation_count = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'D':
                retaliation_count += 1
            else:
                non_retaliation_count += 1
    if non_retaliation_count >= 2 and retaliation_count == 0:
        return 'D'

    # ALLD detection
    if opp_def_rate > 0.95 and n >= 5:
        return 'D'

    # ALLC handling
    if opp_def_count == 0:
        if my_def_count >= 2:
            return 'D'
        if my_def_count == 1:
            if history[-1][0] == 'D':
                return 'C'
            else:
                if n % 10 == 0:
                    return 'D'
                return 'C'
        else:
            if n >= 10 and n % 10 == 0:
                return 'D'
            return 'C'

    # Main logic
    last_my, last_opp = history[-1]

    if last_opp == 'C':
        return 'C'
    else:  # last_opp == 'D'
        if last_my == 'C':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 3:
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.1:
                    return 'C'
                return 'D'
